import sys

ONES = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
        "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen",
        "eighteen", "nineteen"]
TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
SCALES = ["", " thousand", " million", " billion", " trillion"]

def below_thousand(n):
    words = ""
    if n >= 100:
        hundred = n // 100
        words += ONES[hundred] + " hundred "
        n %= 100
    if n >= 20:
        ten = n // 10
        words += TENS[ten] + " "
        n %= 10
    if n > 0:
        words += ONES[n]
    return words.strip()

def to_words(n):
    if n == 0:
        return "zero"
    sign = ""
    if n < 0:
        sign = "minus "
        n = -n
    num_str = str(n).lstrip('0')
    if not num_str:
        return "zero"
    words = below_thousand(int(num_str))
    scale = 0
    while len(num_str) > 3:
        chunk = num_str[-3:]
        chunk_num = int(chunk)
        words = below_thousand(chunk_num) + SCALES[scale] + " " + words
        num_str = num_str[:-3]
        scale += 1
    if num_str:
        words = below_thousand(int(num_str)) + " " + words
    return sign + words.strip()

def main():
    for line in sys.stdin:
        line = line.strip()
        if line:
            try:
                print(to_words(int(line)))
            except ValueError:
                print("Error: invalid input")  # Handle non-integer input

if __name__ == "__main__":
    main()
